package org.example.vendor.vendor;

import jakarta.persistence.*;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.util.UUID;

/** Vendor entity. Events are owned by the event service, which stores this vendor's externalId. */
@Entity
@Getter
@Setter
@NoArgsConstructor
@Table(name = "vendor")
public class Vendor {

    // Internal database key. Never exposed through the API.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Setter(AccessLevel.NONE)
    private Long id;

    // Public id used by clients and other services. Set once, never changes.
    @Column(nullable = false, unique = true, updatable = false)
    @Setter(AccessLevel.NONE)
    private UUID externalId;

    // Not unique: two companies can share a name.
    @Column(nullable = false)
    private String companyName;

    // Stored as plain text for now. Never return it in a response.
    @Column(nullable = false)
    private String password;

    // Unique, so it can serve as the login id later.
    @Column(nullable = false, unique = true)
    private String email;

    private String phone;
    private String website;

    @Column(length = 1000)
    private String description;

    /** Normal constructor: externalId is generated by @PrePersist. */
    public Vendor(String companyName, String password, String email,
                  String phone, String website, String description) {
        this.companyName = companyName;
        this.password = password;
        this.email = email;
        this.phone = phone;
        this.website = website;
        this.description = description;
    }

    /** Fixed-id constructor, used by the dev seeder so test ids survive restarts. */
    public Vendor(UUID externalId, String companyName, String password, String email,
                  String phone, String website, String description) {
        this(companyName, password, email, phone, website, description);
        this.externalId = externalId;
    }

    // Only generates an id when none was given.
    @PrePersist
    void generateExternalId() {
        if (externalId == null) externalId = UUID.randomUUID();
    }
}